var RX_BODY = window.RX_BODY || {};

/* ── ١) الميروبينيم مع الفابوباكتام ───────────────────────── */
RX_BODY['meropenem-vaborbactam'] = {
  what: {
    ar: 'دواء واحد بمادّتين: الميروبينيم مضاد حيوي وريدي من الكاربابينيمات، وهي أوسع فصائل البنسلينات وأقواها ويُحتفظ بها لأصعب العدوى؛ والفابوباكتام ليس مضاداً حيوياً بذاته بل حارس له، مثبّط لإنزيمات البيتالاكتاماز تفرزها بكتيريا صارت تُحلّل الكاربابينيم قبل أن يعمل. الفكرة أن يدخل الحارس أولاً فيعطّل الإنزيم، فيصل المضاد الحيوي سليماً إلى هدفه. لا يوجد منه قرص ولا شراب: مسحوق يُذاب ويُسرّب في الوريد داخل المستشفى تحت إشراف، لأن مكانه هو الحالات التي فشلت فيها الأدوية الأخرى.',
    en: 'One medicine with two substances: meropenem is an intravenous carbapenem antibiotic, the broadest and strongest of the penicillin family, kept in reserve for the hardest infections; vaborbactam is not an antibiotic at all but its bodyguard, an inhibitor of the beta-lactamase enzymes made by bacteria that have learned to destroy carbapenems before they can act. The idea is that the guard goes in first and disables the enzyme, so the antibiotic reaches its target intact. There is no tablet and no syrup: it is a powder dissolved and infused into a vein in hospital under supervision, because its place is where other drugs have already failed.'
  },
  why: {
    ar: 'الاستعمال المعتمد في النشرة الرسمية هو عدوى المسالك البولية المعقّدة عند البالغين، بما فيها التهاب الحويضة والكلية، حين تكون الجرثومة من الإشريكية القولونية أو الكلبسيلة الرئوية أو مجموعة الأمعائية المذنّبة وثبت في المختبر أنها تستجيب له. ومعنى «معقّدة» أن العدوى تجاوزت المثانة البسيطة: قسطرة بولية، أو انسداد، أو حصى، أو خلل تشريحي، أو صعود إلى الكلية. ويُلجأ إليه عملياً حين تُظهر المزرعة بكتيريا مقاومة للكاربابينيم بإنزيم من نوع كيه بي سي، وهي حالة تضيق فيها القائمة كلها إلى أدوية معدودة.',
    en: 'The approved use on the official label is complicated urinary tract infection in adults, including pyelonephritis, when the organism is Escherichia coli, Klebsiella pneumoniae or the Enterobacter cloacae complex and the laboratory has shown it responds. "Complicated" means the infection has moved beyond a simple bladder: a urinary catheter, an obstruction, a stone, an anatomical abnormality, or a climb up to the kidney. In practice it is reached for when the culture shows carbapenem-resistant bacteria carrying a KPC-type enzyme, a situation in which the whole list of options narrows to a handful of drugs.'
  },
  how: {
    ar: 'البكتيريا تبني حول نفسها جداراً يمنحها شكلها ويحفظها من الانفجار بضغط ما بداخلها. يرتبط الميروبينيم ببروتينات تصنع هذا الجدار فيوقف بناءه، فتنشقّ الخلية وتموت؛ ولهذا يوصف بأنه قاتل للجرثومة لا كاتم لنموّها. لكن أنواعاً منها طوّرت إنزيمات تقصّ حلقة الدواء وتبطله. وهنا يعمل الفابوباكتام: يلتصق بهذه الإنزيمات ويشغلها عن الدواء، وهو مثبّط غير انتحاري أي أنه لا يُستهلك في التصاقه، فيبقى فعّالاً ويترك الميروبينيم يصل إلى الجدار ويكمل عمله.',
    en: 'Bacteria build a wall around themselves that gives them their shape and stops them bursting under their own internal pressure. Meropenem binds the proteins that build this wall and halts construction, so the cell splits open and dies; that is why it is called bactericidal rather than merely growth-suppressing. But some strains have evolved enzymes that snip the drug ring open and cancel it. This is where vaborbactam works: it sticks to those enzymes and keeps them busy, and it is a non-suicidal inhibitor, meaning it is not used up by binding, so it stays effective and leaves meropenem free to reach the wall and finish its work.'
  },
  effects: {
    ar: 'أكثر ما سُجّل في التجارب هو الصداع، ثم التهاب الوريد أو ألم واحمرار في موضع التسريب، ثم الإسهال. وقد يظهر غثيان أو تعب أو ارتفاع مؤقّت في إنزيمات الكبد يراه الطبيب في التحاليل ولا يشعر به المريض. ألم موضع الإبرة شائع مع أي تسريب طويل ويُخفّف بتغيير مكان القنية. ولوحظ نقص في الصفيحات الدموية عند من عندهم قصور كلوي، ولم يُبلّغ عنه بنزف. هذه الأعراض في مجملها أخفّ من العدوى التي يُعطى لأجلها، ووجودها لا يعني إيقاف الدواء بل إخبار الفريق المعالج به.',
    en: 'The most frequently recorded effects in trials were headache, then phlebitis or pain and redness at the infusion site, then diarrhoea. Nausea, tiredness or a temporary rise in liver enzymes may appear, seen by the doctor in blood tests and unfelt by the patient. Pain at the needle site is common with any long infusion and eases when the cannula is moved. A fall in platelet count has been observed in people with kidney impairment, without reported bleeding. Taken together these are milder than the infection being treated, and their presence does not mean stopping the drug but telling the treating team about them.'
  },
  warning: {
    ar: 'اطلبي الطوارئ فوراً عند طفح منتشر أو انتفاخ الوجه والشفتين أو اللسان أو ضيق نفس أو دوخة شديدة — فقد سُجّلت تفاعلات تحسّسية شديدة وقاتلة أحياناً، وأكثرها عند من سبقت له حساسية من البنسلين أو السيفالوسبورين. وأبلغي الفريق فوراً عن رجفة موضعية أو ارتجاف عضلي أو تشنّج: الميروبينيم سُجّلت معه نوبات صرعية واضطرابات عصبية، وهي تستدعي تقييماً عصبياً وربما إيقاف الدواء. وأي إسهال مائي شديد أو مصحوب بدم أو مغص وحمّى — أثناء العلاج أو بعده بأسابيع — يجب ألا يُعالَج بدواء مضاد للإسهال من الصيدلية، بل يُبلَّغ به الطبيب لاحتمال التهاب القولون بالمطثّية العسيرة.',
    en: 'Seek emergency care at once for a spreading rash, swelling of the face, lips or tongue, breathlessness or severe dizziness — serious and occasionally fatal hypersensitivity reactions have been recorded, most often in people with a previous penicillin or cephalosporin allergy. Tell the team immediately about focal twitching, muscle jerks or a seizure: seizures and other central nervous system events have been reported with meropenem and call for neurological assessment and possibly stopping the drug. And any severe watery diarrhoea, or one with blood, cramps and fever — during treatment or weeks after it — must not be treated with an anti-diarrhoeal from the pharmacy, but reported to the doctor because of possible Clostridioides difficile colitis.'
  },
  interact: {
    ar: 'أهمّ تعارض هو مع حمض الفالبرويك ومركّب الديفالبروكس المستعملَين في الصرع واضطراب المزاج: الميروبينيم يخفض مستوى الفالبرويك في الدم خفضاً حاداً فتعود النوبات، ولذلك لا يُنصح بجمعهما، ومن كان عليهما يحتاج خطة بديلة يضعها طبيبه قبل البدء. والبروبينسيد يزاحم الدواء على الطرح في الكلية فيرفع مستواه ولا يُجمع معه. وقد يُنقص هذا الدواء فاعلية موانع الحمل الهرمونية، فتلزم وسيلة إضافية أثناء العلاج. وأخبري الفريق بكل دواء تأخذينه، وبأي حساسية سابقة من مضاد حيوي، وبأي مرض في الكلى لأن التصفية الكلوية تحكم الاستعمال.',
    en: 'The most important interaction is with valproic acid and divalproex, used in epilepsy and mood disorder: meropenem drops the blood level of valproate sharply and seizures return, so combining them is not recommended, and anyone on them needs an alternative plan from their doctor before starting. Probenecid competes with the drug for excretion by the kidney and raises its level, so it is not combined either. This medicine may reduce the effectiveness of hormonal contraception, so an additional method is needed during treatment. Tell the team every medicine you take, any previous antibiotic allergy, and any kidney disease, because renal clearance governs how it is used.'
  },
  avoid: {
    ar: 'لا يُعطى لمن ثبتت عنده حساسية من الميروبينيم أو الفابوباكتام أو أي كاربابينيم، ويُتوخّى الحذر الشديد مع من له تاريخ تحسّس شديد من البنسلينات أو السيفالوسبورينات. وهو غير مدروس عند من هم دون سنّ الثامنة عشرة فلا يُستعمل خارج المستشفى المتخصّص. وفي القصور الكلوي تتغيّر طريقة إعطائه ويُعطى بعد جلسة الغسيل لأنه يُنزع بالديال. وفي الحمل: أظهرت الدراسات الحيوانية تشوّهات مع الفابوباكتام بجرعات عالية، فلا يُستعمل إلا إذا رجحت الحاجة الخطر، والقرار للطبيب. والميروبينيم يُفرَز في حليب الأم، فتُناقش الرضاعة مع الفريق المعالج.',
    en: 'It is not given to anyone with proven hypersensitivity to meropenem, vaborbactam or any carbapenem, and great caution is used in people with a history of severe reactions to penicillins or cephalosporins. It has not been studied under the age of eighteen, so it is not used outside a specialist hospital setting. In kidney impairment the way it is given changes, and it is given after a dialysis session because it is removed by dialysis. In pregnancy: animal studies showed malformations with high exposure to vaborbactam, so it is used only if the need outweighs the risk, and that judgement belongs to the doctor. Meropenem passes into breast milk, so breastfeeding is discussed with the treating team.'
  },
  updated: '2026-09-10',
  src: [
    'https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=e237fd0f-3050-42a3-b43e-b6fb4824e93d',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e237fd0f-3050-42a3-b43e-b6fb4824e93d'
  ]
};

/* ── ٢) البلازومايسين ─────────────────────────────────────── */
RX_BODY['plazomicin'] = {
  what: {
    ar: 'مضاد حيوي وريدي من فصيلة الأمينوغليكوزيدات، وهي فصيلة قديمة قوية تضمّ الجنتامايسين والأميكاسين. صُمّم البلازومايسين خصّيصاً ليقاوم الإنزيمات التي طوّرتها البكتيريا لتعطيل أسلافه، فبقي فعّالاً على سلالات صارت لا تستجيب لغيره. لا يوجد منه شكل يُبتلع لأنه لا يُمتصّ من الأمعاء، بل يُسرَّب في الوريد داخل المستشفى. وهو دواء احتياطي بحكم نشرته: يُحجز لمن ضاقت أمامهم البدائل، لا لأنه أقوى بل لأن ثمن أعراضه على الكلى والسمع لا يُدفع إلا عند الحاجة.',
    en: 'An intravenous aminoglycoside antibiotic, an old and powerful family that includes gentamicin and amikacin. Plazomicin was designed specifically to withstand the enzymes bacteria evolved to disable its ancestors, so it remains effective against strains that no longer respond to anything else. There is no swallowed form because it is not absorbed from the gut; it is infused into a vein in hospital. Its own label makes it a reserve drug: it is kept for people whose alternatives have run out, not because it is stronger but because the price it charges on the kidneys and hearing is only worth paying at need.'
  },
  why: {
    ar: 'الاستعمال المعتمد هو عدوى المسالك البولية المعقّدة عند البالغين، بما فيها التهاب الحويضة والكلية، حين تكون الجرثومة إشريكية قولونية أو كلبسيلة رئوية أو متقلّبة رائعة أو أمعائية مذنّبة أثبتت المزرعة استجابتها. والنشرة تقيّده صراحةً: يُحفظ للمرضى الذين لا تتوفّر لهم خيارات علاجية أخرى أو تتوفّر بحدود ضيّقة، لأن بيانات سلامته محدودة. وفي الواقع يظهر اسمه حين تعود المزرعة ببكتيريا مقاومة لعدّة فصائل معاً، وحين يكون البديل الوحيد دواءً أثقل منه أو لا شيء.',
    en: 'The approved use is complicated urinary tract infection in adults, including pyelonephritis, when the organism is Escherichia coli, Klebsiella pneumoniae, Proteus mirabilis or Enterobacter cloacae shown by culture to respond. The label restricts it explicitly: reserve it for patients who have limited or no alternative treatment options, because its safety data are limited. In reality its name comes up when a culture returns bacteria resistant to several classes at once, and when the only alternative is a heavier drug or nothing at all.'
  },
  how: {
    ar: 'تصنع الخلية بروتيناتها في مصانع صغيرة تُسمّى الريبوسومات، وريبوسوم البكتيريا يختلف عن ريبوسومنا اختلافاً يكفي لاستهدافه وحده. يرتبط البلازومايسين بالوحدة الصغرى من ريبوسوم الجرثومة فيُفسد قراءة الشيفرة، فتُبنى بروتينات مشوّهة لا تصلح لشيء وتتوقّف الخلية عن العمل ثم تموت. ولأن الكلية هي التي تُخرجه من الجسم فإنه يتركّز فيها ويتراكم في خلايا الأنبوب الكلوي، وهذا التركّز نفسه هو سبب فائدته في عدوى المسالك وسبب خطره على الكلى في آن واحد.',
    en: 'A cell makes its proteins in small factories called ribosomes, and the bacterial ribosome differs from ours enough to be targeted on its own. Plazomicin binds the small subunit of the bacterial ribosome and corrupts the reading of the code, so misshapen and useless proteins are built, the cell stops functioning and then dies. Because the kidney is what clears it from the body, it concentrates there and builds up inside the cells of the renal tubule, and that same concentration is at once the reason it works so well in urinary infection and the reason it endangers the kidneys.'
  },
  effects: {
    ar: 'أكثر ما سُجّل: تراجع في وظيفة الكلى يظهر في تحليل الكرياتينين، وإسهال، وارتفاع في ضغط الدم، وصداع، وغثيان أو قيء، وأحياناً هبوط في الضغط. وأغلب ارتفاعات الكرياتينين كانت طفيفة ورجعت إلى ما كانت عليه بعد انتهاء العلاج. ولهذا يُفحص عمل الكلى قبل البدء ثم يومياً أثناءه، ويُقاس مستوى الدواء في الدم عند من عندهم ضعف في تصفية الكلية. هذه ليست مبالغة في المتابعة بل هي الشرط الذي يجعل استعمال الدواء آمناً بقدر الإمكان.',
    en: 'The most commonly recorded effects were a decline in kidney function showing on the creatinine test, diarrhoea, raised blood pressure, headache, nausea or vomiting, and sometimes low blood pressure. Most creatinine rises were small and returned towards baseline after treatment ended. That is why kidney function is checked before starting and then daily during treatment, and the drug level in the blood is measured in people with reduced renal clearance. This is not excessive monitoring but the condition that makes using the drug as safe as it can be.'
  },
  warning: {
    ar: 'أبلغي الفريق فوراً عن أي طنين في الأذن أو نقص في السمع أو دوار أو عدم اتزان: هذه علامات تسمّم السمع، وقد لا تظهر إلا بعد انتهاء العلاج، وقد تكون غير قابلة للرجوع. وأبلغي فوراً عن قلّة البول أو انتفاخ الساقين أو ثقل غير مفسّر — علامات أذى الكلى. وضعف عضلي مفاجئ أو صعوبة في التنفّس تستدعي الطوارئ لأن هذه الفصيلة قد تُحدث حصاراً عصبياً عضلياً. واطلبي الطوارئ عند طفح منتشر أو انتفاخ الوجه أو ضيق نفس. وأي إسهال شديد أو دموي أثناء العلاج أو بعده بأسابيع يُبلَّغ به الطبيب ولا يُعالَج ذاتياً.',
    en: 'Tell the team at once about any ringing in the ears, hearing loss, vertigo or unsteadiness: these are signs of ototoxicity, they may not appear until after treatment has finished, and they may be irreversible. Report immediately any drop in urine output, swelling of the legs or unexplained heaviness — signs of kidney injury. Sudden muscle weakness or difficulty breathing needs emergency care, because this class can cause neuromuscular blockade. Seek emergency care for a spreading rash, facial swelling or breathlessness. And any severe or bloody diarrhoea during treatment or in the weeks after must be reported to the doctor, never self-treated.'
  },
  interact: {
    ar: 'الخطر الأكبر ليس تفاعلاً كيميائياً بل تراكم الأذى: جمع البلازومايسين مع أدوية أخرى ثقيلة على الكلى — كمضادات الالتهاب غير الستيرويدية، وبعض مدرّات البول القوية، وأمفوتريسين ب، والسيسبلاتين، ومثبّطات المناعة كالسيكلوسبورين والتاكروليمس — يضاعف احتمال الفشل الكلوي. وكذلك جمعه مع دواء آخر سامّ للسمع يزيد خطر فقدانه. ومرخيات العضلات المستعملة في التخدير قد يشتدّ أثرها معه. وأخبري الفريق إن كان في العائلة صمم مبكّر بعد مضاد حيوي، فبعض الناس يحملون طفرة وراثية في المتقدّرات تجعل السمع شديد الهشاشة أمام هذه الفصيلة.',
    en: 'The greatest danger is not a chemical reaction but accumulated harm: combining plazomicin with other drugs that burden the kidney — non-steroidal anti-inflammatories, some powerful diuretics, amphotericin B, cisplatin, and immunosuppressants such as ciclosporin and tacrolimus — multiplies the chance of renal failure. Likewise, pairing it with another ear-toxic drug increases the risk of hearing loss. Muscle relaxants used in anaesthesia may have their effect deepened. Tell the team if anyone in the family went deaf early after an antibiotic: some people carry a mitochondrial variant that makes hearing extremely fragile in front of this class.'
  },
  avoid: {
    ar: 'ممنوع على من عنده حساسية معروفة من أي مضاد حيوي أمينوغليكوزيدي. وممنوع في الحمل: هذه الفصيلة تعبر المشيمة وقد تُحدث صمماً خلقياً غير قابل للرجوع عند الجنين، وهذا بند صريح في التحذير المؤطّر، فتُستعمل وسيلة منع حمل موثوقة أثناء العلاج. ولا توجد بيانات بشرية عن الرضاعة فتُناقش مع الفريق. ويُتوخّى الحذر الشديد عند كبار السنّ وعند كل من عنده قصور كلوي سابق، وعند من عنده مرض عصبي عضلي كالوهن العضلي الوبيل. وهو غير مدروس عند الأطفال. ولا يُبدأ إطلاقاً بلا فحص وظيفة الكلى ومتابعة يومية.',
    en: 'It is forbidden in anyone with known hypersensitivity to any aminoglycoside antibiotic. It is forbidden in pregnancy: this class crosses the placenta and can cause irreversible congenital deafness in the fetus, an explicit item in the boxed warning, so reliable contraception is used during treatment. There are no human data on breastfeeding, so it is discussed with the team. Great caution applies in older people and in anyone with pre-existing kidney impairment, and in anyone with a neuromuscular disease such as myasthenia gravis. It has not been studied in children. And it is never started without a kidney function test and daily monitoring.'
  },
  updated: '2026-09-10',
  src: [
    'https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=1243fcd3-de84-428b-901e-d83d65e4d98c',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0b82ffed-27f4-4f5c-8135-670c148f0e12'
  ]
};

/* ── ٣) البوليميكسين ب ────────────────────────────────────── */
RX_BODY['polymyxin-b'] = {
  what: {
    ar: 'مضاد حيوي قديم اكتُشف قبل عقود ثم كاد يُهجر لسمّيته على الكلى والأعصاب، ثم أعادته إلينا البكتيريا نفسها: صارت سلالات سالبة الغرام تقاوم كل شيء تقريباً، فعاد البوليميكسين ب خطّ العلاج الأخير. له وجهان: مسحوق يُسرَّب في الوريد داخل المستشفى للعدوى الشديدة، وصور موضعية أهدأ بكثير يعرفها الناس أكثر — قطرات للعين وقطرات للأذن ومراهم جلدية، غالباً مخلوطاً بمضاد حيوي آخر أو بكورتيزون. وقد يُبخَّر للاستنشاق في بعض حالات الرئة المزمنة خارج الاستعمال المعتمد.',
    en: 'An old antibiotic discovered decades ago and then nearly abandoned for its toxicity to kidneys and nerves, until the bacteria themselves brought it back: gram-negative strains now resist almost everything, so polymyxin B has returned as a last line of treatment. It has two faces: a powder infused into a vein in hospital for severe infection, and much gentler topical forms that people know better — eye drops, ear drops and skin ointments, usually mixed with another antibiotic or with a steroid. It is also sometimes nebulised for inhalation in certain chronic lung conditions outside its approved use.'
  },
  why: {
    ar: 'يُستعمل بالوريد للعدوى الخطيرة ببكتيريا شديدة المقاومة سالبة الغرام: الزائفة الزنجارية، والأمعائيات، والراكدة البومانية — أي عدوى الدم والرئة والمسالك في المستشفى حين تفشل الكاربابينيمات. ويُعطى في السحايا بحقن داخل القراب من مستحضر خالٍ من المواد الحافظة وحده. أما موضعياً فيدخل في علاج التهاب الملتحمة الجرثومي والتهاب الأذن الخارجية والجروح السطحية. وله استعمال غير معتمد بالاستنشاق في عدوى الرئة المزمنة عند مرضى التليّف الكيسي. وليس له مكان في نزلات البرد ولا في أي عدوى تُعالَج بدواء أخفّ منه.',
    en: 'It is used intravenously for serious infection with highly resistant gram-negative bacteria: Pseudomonas aeruginosa, Enterobacteriaceae and Acinetobacter baumannii — that is, hospital bloodstream, lung and urinary infection when carbapenems have failed. For meningitis it is given by intrathecal injection using a preservative-free preparation only. Topically it is part of treatment for bacterial conjunctivitis, otitis externa and superficial wounds. It has an unapproved inhaled use for chronic lung infection in cystic fibrosis. It has no place in a common cold, nor in any infection that a lighter drug can treat.'
  },
  how: {
    ar: 'غلاف البكتيريا سالبة الغرام مشحون بشحنة سالبة بسبب دهون خاصة فيه. وجزيء البوليميكسين ب مشحون بشحنة موجبة، فينجذب إلى الغلاف انجذاباً كهربائياً ويزيح الأيونات التي كانت تشدّه ويثبّته. فيتخلخل الغشاء وتفتح فيه ثغرات، فيتسرّب ما بداخل الخلية إلى الخارج وتموت الجرثومة. وهو قاتل مباشر لا يحتاج أن تكون الخلية منقسمة. وله ميزة إضافية: يرتبط بالسمّ الداخلي الذي يتحرّر من البكتيريا الميتة فيعادله جزئياً. ولأنه يعمل على غشاء دهني فإنه يمسّ أغشيتنا أيضاً بدرجة أقلّ، وهنا أصل سمّيته.',
    en: 'The envelope of a gram-negative bacterium carries a negative charge because of the special lipids in it. The polymyxin B molecule carries a positive charge, so it is drawn to that envelope electrically and displaces the ions that were holding it together and stabilising it. The membrane destabilises, pores open in it, the contents of the cell leak out and the bacterium dies. It kills directly and does not need the cell to be dividing. It has an added advantage: it binds the endotoxin released from dead bacteria and partly neutralises it. And because it works on a lipid membrane it touches our membranes too, to a lesser degree, which is the root of its toxicity.'
  },
  effects: {
    ar: 'بالوريد: أشيع ما يُلاحَظ هو خدر أو وخز حول الفم وفي أطراف اليدين والقدمين، ودوخة، وتشوّش بصر، ونعاس أو تهيّج. وفي الكلى يظهر الأثر في التحاليل قبل أن يشعر به المريض: بروتين في البول، وأسطوانات خلوية، وارتفاع اليوريا والكرياتينين. وموضعياً الأمر مختلف تماماً: قطرة العين قد تُحدث لسعاً أو احمراراً أو تحسّساً موضعياً، والمرهم قد يسبّب حكّة أو طفحاً مكان وضعه، ولا تُنقل تحذيرات الحقن الوريدي إلى القطرة. والاستنشاق قد يُحدث تضيّقاً في الشعب وسعالاً.',
    en: 'Intravenously: the commonest effects are numbness or tingling around the mouth and in the hands and feet, dizziness, blurred vision, and drowsiness or irritability. In the kidney the effect appears in blood and urine tests before the patient feels it: protein in the urine, cellular casts, and rising urea and creatinine. Topically the picture is entirely different: eye drops may sting, redden the eye or cause local sensitivity, and the ointment may cause itching or a rash where it is applied — the warnings for intravenous use do not transfer to the drop. Inhalation may trigger bronchospasm and coughing.'
  },
  warning: {
    ar: 'أثناء العلاج الوريدي، أبلغي الفريق فوراً عن نقص كمية البول أو انقطاعه — هذا مع ارتفاع اليوريا سبب مباشر لإيقاف الدواء. واطلبي المساعدة فوراً عند ضعف عضلي متزايد أو ثقل في التنفّس أو تلعثم في الكلام: هذه علامات الحصار العصبي العضلي وقد تنتهي بالحاجة إلى جهاز تنفّس. وأبلغي عن أي خدر جديد أو تشوّش بصر لأنه ينذر بارتفاع مستوى الدواء. وبعد الحقن داخل القراب: حمّى وصداع وتيبّس رقبة تستدعي فحصاً فورياً. وموضعياً: أوقفي القطرة أو المرهم وراجعي إن زاد الاحمرار والألم أو ظهر طفح أو لم تتحسّن العدوى.',
    en: 'During intravenous treatment, tell the team at once if urine output falls or stops — that, together with a rising urea, is a direct reason to discontinue. Get help immediately for increasing muscle weakness, heaviness of breathing or slurred speech: these are signs of neuromuscular blockade and can end in needing a ventilator. Report any new numbness or blurred vision, as it warns that the drug level is rising. After intrathecal injection: fever, headache and a stiff neck need immediate assessment. Topically: stop the drop or ointment and seek review if redness and pain increase, a rash appears, or the infection does not improve.'
  },
  interact: {
    ar: 'الخطر يتراكم لا يتفاعل: جمعه مع دواء آخر ثقيل على الكلى — كالأمينوغليكوزيدات، وأمفوتريسين ب، والسيسبلاتين، ومضادات الالتهاب غير الستيرويدية، ومثبّطات المناعة — يزيد احتمال الفشل الكلوي كثيراً. وجمعه مع مرخيات العضلات المستعملة في التخدير، أو مع أدوية أخرى تُضعف النقل العصبي العضلي، قد يوقف التنفّس. ويُتوخّى الحذر مع الأدوية التي تُنقص السمع لأن السمّية تتضافر. أما القطرة والمرهم فتعارضاتهما محدودة، لكن يُنبَّه إلى عدم خلط قطرات مختلفة في العين أو الأذن بلا استشارة، وإلى ترك فاصل بين قطرة وأخرى.',
    en: 'The danger accumulates rather than reacts: combining it with another drug that burdens the kidney — aminoglycosides, amphotericin B, cisplatin, non-steroidal anti-inflammatories, immunosuppressants — greatly increases the chance of renal failure. Combining it with muscle relaxants used in anaesthesia, or with other drugs that weaken neuromuscular transmission, can stop breathing. Caution applies with hearing-toxic drugs because toxicities compound. The drop and the ointment have limited interactions, but different drops should not be mixed in the eye or ear without advice, and a gap should be left between one drop and the next.'
  },
  avoid: {
    ar: 'ممنوع على من عنده حساسية معروفة من البوليميكسين ب أو من الكوليستين أو من مكوّنات المستحضر. والاستعمال الوريدي أو داخل القراب لا يكون إلا لمريض داخل المستشفى تحت إشراف مستمر. ويُقلَّل ويُراقَب بشدّة عند من عنده مرض كلوي أو احتباس نيتروجيني، وعند كبار السنّ. ويُتوخّى حذر شديد عند من عنده مرض عصبي عضلي. وفي الحمل والرضاعة يُوزَن الاستعمال الجهازي بحذر ولا يكون إلا لضرورة يقدّرها الطبيب. أما القطرة والمرهم فاستعمالهما أبسط بكثير، ومع ذلك لا يُستعملان في العين أو الأذن بلا تشخيص، ولا تُوضع قطرة الأذن مع ثقب في الطبلة إلا بإذن طبيب.',
    en: 'It is forbidden in anyone with known hypersensitivity to polymyxin B, to colistin or to the formulation. Intravenous or intrathecal use is only for a hospitalised patient under constant supervision. It is reduced and closely monitored in anyone with kidney disease or nitrogen retention, and in older people. Great caution applies in anyone with neuromuscular disease. In pregnancy and breastfeeding systemic use is weighed carefully and only for a necessity the doctor judges. The drop and the ointment are far simpler, yet still are not used in the eye or ear without a diagnosis, and ear drops are not used with a perforated eardrum except on a doctor’s instruction.'
  },
  updated: '2026-09-10',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK557540/',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=132fe072-9c9a-4c56-9004-c27ee6a467ae'
  ]
};

/* ── ٤) الفلوكونازول ──────────────────────────────────────── */
RX_BODY['fluconazole'] = {
  what: {
    ar: 'مضاد فطريات من فصيلة الترايازولات، وهو من أكثر مضادات الفطريات استعمالاً في العالم لأنه يُبتلع ويُمتصّ امتصاصاً ممتازاً وينتشر في سوائل الجسم كلها بما فيها السائل الدماغي الشوكي. يوجد كبسولات وشراباً ومحلولاً وريدياً. يعمل ببطء نموّ الفطر لا بقتله فوراً، ولهذا يحتاج جهازاً مناعياً يكمل المهمّة. وهو دواء بسيط في مظهره ثقيل في تفاصيله: كبسولة واحدة قد تكفي لعلاج شائع، وقد يُعطى شهوراً في عدوى عميقة، وبينهما تختلف كل الاعتبارات.',
    en: 'A triazole antifungal, among the most used antifungals in the world because it is swallowed, absorbed excellently and spreads through all body fluids including the cerebrospinal fluid. It comes as capsules, a liquid and an intravenous solution. It works by slowing the growth of the fungus rather than killing it outright, so it needs an immune system to finish the job. It is a simple-looking drug with heavy detail: a single capsule may settle a common complaint, while months of it may be needed for a deep infection, and between those two everything about the calculation changes.'
  },
  why: {
    ar: 'يُستعمل لعدوى الخمائر، وأشهرها فطريات المهبل، والقلاع في الفم والحلق، وفطريات المريء التي تسبّب ألماً عند البلع، وفطريات الحشفة عند الرجال. ويُعطى في التهاب السحايا الفطري بالمستخفية وهو استعمال طويل جادّ لا علاقة له بالكبسولة الواحدة. ويُستعمل وقايةً من عدوى الخمائر عند من ضعفت مناعتهم: مرضى الكيماوي، ومن يخضعون لزرع نخاع العظم، ومرضى نقص المناعة. وهو لا ينفع في عدوى الفطر الجلدي كسعفة القدم إلا في حدود، ولا يعالج عدوى بكتيرية إطلاقاً.',
    en: 'It is used for yeast infection, most familiarly vaginal thrush, thrush of the mouth and throat, oesophageal thrush that makes swallowing painful, and candidal balanitis in men. It is given in cryptococcal fungal meningitis, a long and serious course that has nothing to do with the single capsule. And it is used to prevent yeast infection in people whose immunity is weakened: those on chemotherapy, those undergoing bone marrow transplant, and people with immune deficiency. It is of limited use in dermatophyte infections such as athlete’s foot, and it does not treat bacterial infection at all.'
  },
  how: {
    ar: 'غشاء الخلية الفطرية يحتاج مادّة دهنية اسمها الإرغوستيرول، وهي عند الفطر بمنزلة الكوليسترول عندنا: تمنح الغشاء تماسكه ومرونته. ويعطّل الفلوكونازول إنزيماً يعتمد على السيتوكروم بي أربعمئة وخمسين يحوّل مادّة أوّلية إلى إرغوستيرول. فيقلّ الإرغوستيرول وتتراكم مواد وسيطة، فيصير الغشاء رخواً منفذاً لا يحفظ ما بداخله، فيتوقّف نموّ الفطر. والمهمّ أن الإنزيم المستهدف من عائلة إنزيمات موجودة في كبدنا أيضاً، ومن هنا يأتي أثره في استقلاب أدوية أخرى وكثرة تعارضاته.',
    en: 'The fungal cell membrane needs a fatty substance called ergosterol, which is to a fungus what cholesterol is to us: it gives the membrane its cohesion and flexibility. Fluconazole disables a cytochrome P450-dependent enzyme that converts a precursor into ergosterol. Ergosterol falls, intermediate substances accumulate, and the membrane becomes slack and leaky and no longer holds what is inside it, so the fungus stops growing. What matters is that the targeted enzyme belongs to a family that exists in our liver too, and from that comes its effect on the metabolism of other medicines and its long list of interactions.'
  },
  effects: {
    ar: 'أكثر ما يُشتكى منه: صداع، وألم في المعدة، وإسهال، وغثيان أو قيء، وطفح جلدي بسيط، وأحياناً دوخة أو تغيّر في حاسّة التذوّق أو حرقة في المعدة. وأغلب هذه الأعراض أخفّ ما تكون مع الكبسولة الواحدة وأوضح مع العلاج الممتدّ. الصداع يخفّ بالراحة وشرب الماء وتقليل الكحول، والغثيان يخفّ بأخذ الدواء بعد الأكل وبوجبات بسيطة صغيرة. والطفح البسيط قد يُعالَج بمضاد هيستامين من الصيدلية — أما الطفح المتقشّر أو المتقرّح فمسألة أخرى تماماً تجدينها في التحذير.',
    en: 'The commonest complaints are headache, stomach pain, diarrhoea, nausea or vomiting, a mild rash, and sometimes dizziness, an altered sense of taste or heartburn. Most of these are at their mildest with a single capsule and clearest with extended treatment. Headache eases with rest, drinking fluids and limiting alcohol; nausea eases by taking the medicine after food and eating small plain meals. A mild rash may be treated with an antihistamine from the pharmacy — but a peeling or blistering rash is an entirely different matter, described in the warning.'
  },
  warning: {
    ar: 'اتصلي بالطبيب فوراً إن اصفرّ بياض العينين أو الجلد، أو صار البول داكناً والبراز شاحباً، أو فقدت شهيتك مع تعب غير مفسّر — علامات أذى الكبد، والدواء يُوقف عندها. واطلبي مساعدة عاجلة إن تسارعت ضربات القلب أو اضطربت أو أُغمي عليك، فقد سُجّلت مع الفلوكونازول إطالة في فترة كيو تي واضطراب نظم خطير. وأبلغي فوراً إن صرت تُكدَمين بسهولة أو تلتقطين العدوى بسرعة. واطلبي الإسعاف عند انتفاخ الشفتين أو اللسان أو الحلق أو ضيق النفس المفاجئ، وعند أي طفح ينتفخ أو يتقرّح أو يتقشّر — فقد يكون متلازمة ستيفنز جونسون.',
    en: 'Call a doctor at once if the whites of the eyes or the skin turn yellow, the urine darkens and stools go pale, or appetite disappears with unexplained tiredness — signs of liver injury, at which the drug is stopped. Get urgent help if the heartbeat becomes fast or irregular or you faint, as QT prolongation and dangerous rhythm disturbance have been recorded with fluconazole. Report immediately if you start bruising easily or catching infections quickly. Call the emergency services for swelling of the lips, tongue or throat or sudden breathlessness, and for any rash that swells, blisters or peels — it may be Stevens-Johnson syndrome.'
  },
  interact: {
    ar: 'قائمته طويلة لأنه يعطّل إنزيمات الكبد فترتفع مستويات أدوية أخرى. أخبري طبيبك إن كنت تأخذين: الوارفارين أو الدابيغاتران أو الكلوبيدوغريل، أو ستاتيناً لخفض الكوليسترول، أو الكاربامازيبين، أو الأميودارون، أو الليثيوم، أو مضادات ذهان كالبيموزيد والكويتيابين والهالوبيريدول والريسبيريدون والأميسولبريد، أو مضادات اكتئاب كالإسيتالوبرام والفينلافاكسين، أو الإريثرومايسين والكلاريثرومايسين، أو الإرغوتامين للشقيقة، أو اللوسارتان. وجمعه مع الكينيدين ممنوع لخطر اضطراب النظم. ولا تُوثق سلامة الأعشاب والمكمّلات معه لأنها لا تُختبر أصلاً على تفاعلها مع الأدوية.',
    en: 'Its list is long because it disables liver enzymes and so raises the levels of other medicines. Tell your doctor if you take warfarin, dabigatran or clopidogrel; a statin for cholesterol; carbamazepine; amiodarone; lithium; antipsychotics such as pimozide, quetiapine, haloperidol, risperidone or amisulpride; antidepressants such as escitalopram or venlafaxine; erythromycin or clarithromycin; ergotamine for migraine; or losartan. Combining it with quinidine is contraindicated because of rhythm disturbance. Herbal products and supplements cannot be assumed safe with it, because they are not tested for their effect on other medicines in the first place.'
  },
  avoid: {
    ar: 'يُتجنّب في الحمل، وخاصة الثلث الأول، لِما رُصد من خطر على الجنين مع الاستعمال الممتدّ، والقرار في أي حالة للطبيب وحده. ولا يُنصح به أثناء الرضاعة. ويحتاج حذراً ومتابعة عند من عنده مرض في الكبد أو الكلى، وعند من عنده مرض في القلب أو اضطراب في نظمه أو خلل في أملاح الدم. وممنوع مع الكينيدين. ويُخبَر الطبيب بأي حساسية سابقة من دواء من فصيلة الآزولات. وأخيراً: حكّة مهبلية تظهر لأول مرة، أو تتكرّر كثيراً، أو تصاحبها حمّى وألم في أسفل البطن، تحتاج تشخيصاً قبل أي كبسولة.',
    en: 'It is avoided in pregnancy, especially the first trimester, because of observed fetal risk with extended use; in any individual case the decision belongs to the doctor alone. It is not recommended while breastfeeding. It needs caution and monitoring in anyone with liver or kidney disease, and in anyone with heart disease, a rhythm disturbance or a salt imbalance in the blood. It is contraindicated with quinidine. Tell the doctor about any previous allergy to an azole medicine. And finally: vaginal itching appearing for the first time, or recurring often, or coming with fever and lower abdominal pain, needs a diagnosis before any capsule.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a690002.html',
    'https://www.nhs.uk/medicines/fluconazole/side-effects-of-fluconazole/',
    'https://www.nhs.uk/medicines/fluconazole/taking-fluconazole-with-other-medicines-and-herbal-supplements/',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f694c617-3383-416c-91b6-b94fda371204'
  ]
};

/* ── ٥) الإتراكونازول ─────────────────────────────────────── */
RX_BODY['itraconazole'] = {
  what: {
    ar: 'مضاد فطريات من الترايازولات، أوسع مدى من الفلوكونازول لأنه يصل إلى فطريات لا يمسّها ذاك، ومنها الرشاشيات وفطريات الأظافر. يوجد كبسولات ومحلولاً فموياً، ولكل شكل شروط امتصاص مختلفة: الكبسولة تحتاج معدة حامضية ووجبة كاملة، والمحلول يُؤخذ على معدة خالية. وهو من الأدوية التي لا تُقاس بقوّتها وحدها: تحمل نشرته تحذيراً مؤطّراً بقصور القلب، وقائمة أدوية ممنوع جمعها معه لأن الجمع قد ينتهي باضطراب نظم قاتل.',
    en: 'A triazole antifungal, broader in reach than fluconazole because it touches fungi that one cannot, among them Aspergillus and nail fungus. It comes as capsules and as an oral solution, and each form has different absorption requirements: the capsule needs an acidic stomach and a full meal, while the solution is taken on an empty stomach. It is one of those drugs not measured by strength alone: its label carries a boxed warning about heart failure and a list of medicines that must not be combined with it, because the combination can end in a fatal rhythm disturbance.'
  },
  why: {
    ar: 'الاستعمالات المعتمدة في النشرة: فطريات الأظافر في اليد والقدم، وداء الفطر البرعمي في الرئة وخارجها، وداء النوسجات بصوره المزمنة والمنتشرة، وداء الرشاشيات عند من لا يتحمّل أمفوتريسين ب أو لم يستجب له. ويُستعمل المحلول الفموي لفطريات الفم والحلق والمريء. ويُستعمل أيضاً للوقاية من العدوى الفطرية عند من ضعفت مناعتهم كمرضى نقص المناعة البشري. وله مكان في النخالية المبرقشة وفي التهاب الجيوب الفطري. وقبل أن يُوصف لفطر الأظافر يُفضَّل تأكيد التشخيص بمزرعة، فليس كل ظفر متغيّر ظفراً مصاباً بالفطر.',
    en: 'The approved uses on the label are: fungal infection of the fingernails and toenails, blastomycosis of the lung and beyond it, histoplasmosis in its chronic and disseminated forms, and aspergillosis in people intolerant of or refractory to amphotericin B. The oral solution is used for thrush of the mouth, throat and gullet. It is also used to prevent fungal infection in people with weakened immunity such as those with HIV. It has a place in pityriasis versicolor and in fungal sinusitis. Before it is prescribed for a nail, confirming the diagnosis by culture is preferred, since not every changed nail is a fungal one.'
  },
  how: {
    ar: 'مثل بقيّة الآزولات، يعطّل الإتراكونازول الإنزيم المعتمد على السيتوكروم بي أربعمئة وخمسين الذي يصنع الإرغوستيرول، وهو المادّة التي يقوم عليها غشاء الخلية الفطرية. فينهار تماسك الغشاء ويتوقّف الفطر عن النموّ. وميزته أنه يذوب في الدهون فيتراكم في الجلد وصفيحة الظفر ويبقى فيهما مدّة بعد آخر قرص، ولهذا ينفع في فطر الأظافر الذي يعجز عنه غيره. وضريبة هذه القدرة أنه يعطّل الإنزيم الكبدي نفسه الذي يستقلب أدوية كثيرة، فترتفع مستوياتها ارتفاعاً خطيراً — وهذا هو أصل قائمة الممنوعات معه.',
    en: 'Like the other azoles, itraconazole disables the cytochrome P450-dependent enzyme that makes ergosterol, the substance the fungal cell membrane is built on. The membrane loses its cohesion and the fungus stops growing. Its advantage is that it dissolves in fat, so it accumulates in the skin and the nail plate and stays there for a time after the last dose, which is why it works on nail fungus where others fail. The price of that ability is that it disables the very liver enzyme that metabolises many medicines, so their levels rise dangerously — and that is the origin of its list of forbidden combinations.'
  },
  effects: {
    ar: 'أكثر ما يُشتكى منه: غثيان وقيء وإسهال أو إمساك وألم في المعدة، وصداع، وطفح جلدي، وطعم غير مستساغ في الفم. وقد يظهر انتفاخ في القدمين أو ارتفاع في الضغط أو دوخة، وقد يشتكي بعضهم من ألم في المفاصل أو العضلات، أو من نقص الرغبة الجنسية وضعف الانتصاب. وحين يمتدّ العلاج تصير متابعة الكبد بالتحاليل جزءاً من الخطّة لا رفاهية. وانتفاخ الساقين تحديداً لا يُهمَل ولا يُفسَّر بالحرّ أو بطول الوقوف قبل أن يراه الطبيب، لأنه قد يكون أول علامة على شيء في القلب.',
    en: 'The commonest complaints are nausea, vomiting, diarrhoea or constipation, stomach pain, headache, rash and an unpleasant taste in the mouth. Swelling of the feet, raised blood pressure or dizziness may appear, and some people report joint or muscle pain, or reduced sexual desire and erectile difficulty. When treatment is extended, monitoring the liver with blood tests becomes part of the plan rather than a luxury. Swelling of the legs in particular is not to be dismissed or explained away by heat or long standing before a doctor has seen it, because it may be the first sign of something in the heart.'
  },
  warning: {
    ar: 'اطلبي المساعدة فوراً عند ضيق نفس، أو سعال ببلغم أبيض أو ورديّ، أو تعب شديد غير مفسّر، أو تسارع نبض، أو انتفاخ القدمين والكاحلين والساقين — هذه علامات قصور القلب وهي مضمون التحذير المؤطّر، والدواء يُوقف عندها. واتصلي بالطبيب فوراً عند اصفرار العينين أو الجلد أو بول داكن أو براز شاحب أو فقدان شهية — فقد سُجّلت حالات نادرة من فشل كبدي، بعضها في الأسبوع الأول. وأبلغي فوراً عن خدر أو وخز أو ضعف في الأطراف، أو نقص في السمع، أو خفقان أو إغماء. واطلبي الإسعاف عند طفح مع ضيق نفس أو انتفاخ الوجه، أو جلد يتقرّح ويتقشّر.',
    en: 'Get help immediately for breathlessness, a cough with white or pink phlegm, severe unexplained tiredness, a fast heartbeat, or swelling of the feet, ankles or legs — these are the signs of heart failure that the boxed warning is about, and the drug is stopped when they appear. Call the doctor at once for yellowing of the eyes or skin, dark urine, pale stools or loss of appetite: rare cases of liver failure have been recorded, some within the first week. Report immediately any numbness, tingling or weakness in the limbs, any hearing loss, palpitations or fainting. Seek emergency care for a rash with breathlessness or facial swelling, or skin that blisters and peels.'
  },
  interact: {
    ar: 'قائمة الممنوع جمعها معه طويلة وصريحة في النشرة، ومنها: الميثادون، والديسوبيراميد، والدوفيتيليد، والدرونيدارون، والكينيدين، وقلويدات الشقران، والبيموزيد، والميدازولام الفموي، والترايازولام، والفيلوديبين، والنيسولديبين، والإيفابرادين، والرانولازين، والإبليرينون، والسيسابريد، واللوفاستاتين، والسيمفاستاتين، واللوميتابيد، والتيكاغريلور. الجمع يرفع مستوياتها فيُطيل فترة كيو تي وقد يُحدث تسرّعاً بطينياً. ومن الجهة الأخرى: مضادات الحموضة ومثبّطات مضخّة البروتون وحاصرات إتش اثنين تُنقص امتصاص الكبسولة إنقاصاً شديداً فيفشل العلاج. ولا يُبدأ دواء جديد أثناءه إلا بعد مراجعة القائمة مع الصيدلي.',
    en: 'The list of forbidden combinations is long and explicit on the label, including methadone, disopyramide, dofetilide, dronedarone, quinidine, ergot alkaloids, pimozide, oral midazolam, triazolam, felodipine, nisoldipine, ivabradine, ranolazine, eplerenone, cisapride, lovastatin, simvastatin, lomitapide and ticagrelor. Combining raises their levels, prolongs the QT interval and can cause ventricular tachyarrhythmia. From the other direction: antacids, proton pump inhibitors and H2 blockers sharply reduce absorption of the capsule, so treatment fails. No new medicine should be started during it without reviewing the list with a pharmacist.'
  },
  avoid: {
    ar: 'ممنوع في الحمل ولمن تخطّط للحمل، وتُستعمل وسيلة منع حمل موثوقة أثناء العلاج وبعده بفترة يحدّدها الطبيب. وممنوع لعلاج فطر الأظافر عند من عنده دليل على خلل في وظيفة البطين أو قصور قلب أو تاريخ قصور قلب — وهذا نصّ التحذير المؤطّر. وممنوع مع أي دواء من قائمة الممنوعات، ولمن عنده حساسية من الإتراكونازول. ويحتاج حذراً ومتابعة عند من عنده مرض كبدي أو كلوي، وعند كبار السنّ، وعند من يعاني نقص حموضة المعدة. ولا يُنصح به أثناء الرضاعة. وقبل الوصف يُخبَر الطبيب بكل دواء ومكمّل، فالقائمة أطول من أن تُحفظ.',
    en: 'It is contraindicated in pregnancy and in women contemplating pregnancy, and reliable contraception is used during treatment and for a period afterwards set by the doctor. It must not be used for nail fungus in anyone with evidence of ventricular dysfunction, heart failure or a history of heart failure — that is the text of the boxed warning. It is contraindicated with any drug on the forbidden list, and in anyone allergic to itraconazole. It needs caution and monitoring in liver or kidney disease, in older people, and in anyone with reduced stomach acid. It is not recommended while breastfeeding. Before prescribing, tell the doctor every medicine and supplement — the list is too long to memorise.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a692049.html',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2ab38a8a-3708-4b97-9f7f-8e554a15348d'
  ]
};

/* ── ٦) الفوريكونازول ─────────────────────────────────────── */
RX_BODY['voriconazole'] = {
  what: {
    ar: 'مضاد فطريات من الترايازولات، صُنع للعدوى الفطرية الغازية التي تهدّد الحياة، وهو الخيار الأول في داء الرشاشيات الغازي. يوجد أقراصاً ومسحوقاً للشراب ومحلولاً وريدياً، فينتقل المريض من الوريد إلى الفم حين يتحسّن. وهو دواء مستشفى بامتياز: يُتابَع بتحاليل كبد وبقياس مستواه في الدم عند كثيرين، لأن استقلابه يختلف اختلافاً كبيراً بين شخص وآخر بحسب إنزيمات وراثية. ويُعرف بأثرَين مميّزَين: تشوّش بصري مؤقّت، وحساسية شديدة للشمس مع طول الاستعمال.',
    en: 'A triazole antifungal made for life-threatening invasive fungal infection, and the first choice in invasive aspergillosis. It comes as tablets, a powder for suspension and an intravenous solution, so a patient moves from the vein to the mouth as they improve. It is very much a hospital drug: it is followed with liver tests and, in many people, by measuring its level in the blood, because its metabolism varies greatly from person to person according to inherited enzymes. It is known for two distinctive effects: temporary visual disturbance, and severe sun sensitivity with long use.'
  },
  why: {
    ar: 'الاستعمالات المعتمدة: داء الرشاشيات الغازي، وفطر الدم بالمبيضات عند غير المصابين بنقص العدلات، وفطريات المريء، والعدوى الخطيرة بفطر السيدوسبوريوم الأبيوسبرمي وبالفوزاريوم عند من لا يتحمّل غيره أو لم يستجب له. وهذه كلها عدوى تصيب من ضعفت مناعتهم: مرضى الكيماوي وزرع النخاع، ومن يأخذون مثبّطات مناعة، ومرضى نقص المناعة البشري، ومن طالت إقامتهم في العناية المركّزة. وله دور في التهاب الجيوب الفطري الغازي وفي التهاب الرئة الفطري. وهو لا يُعطى لعدوى فطرية سطحية بسيطة، فالثمن أكبر من الحاجة.',
    en: 'The approved uses are invasive aspergillosis; candidaemia in non-neutropenic patients; oesophageal candidiasis; and serious infection with Scedosporium apiospermum and Fusarium species in people intolerant of or refractory to other treatment. All of these strike people whose immunity is weakened: those on chemotherapy or after bone marrow transplant, those on immunosuppressants, people with HIV, and those with a long stay in intensive care. It has a role in invasive fungal sinusitis and in fungal pneumonia. It is not given for a simple superficial fungal infection, where the price is greater than the need.'
  },
  how: {
    ar: 'يعطّل الفوريكونازول الإنزيم الفطري الذي يحوّل اللانوستيرول إلى إرغوستيرول، وهو حجر الأساس في غشاء الخلية الفطرية. فيقلّ الإرغوستيرول وتتراكم مواد وسيطة سامّة للفطر نفسه، فيتوقّف النموّ وينهار الغشاء. وارتباطه بهذا الإنزيم أشدّ التصاقاً من الآزولات الأقدم، ولهذا يصل إلى الرشاشيات التي لا يمسّها الفلوكونازول. أما ما يجعل استعماله دقيقاً فهو أن الكبد يستقلبه بإنزيمات يختلف نشاطها وراثياً بين الناس، فيرتفع مستواه عند بعضهم ويهبط عند آخرين بالجرعة نفسها — ولهذا يُقاس مستواه في الدم.',
    en: 'Voriconazole disables the fungal enzyme that converts lanosterol into ergosterol, the cornerstone of the fungal cell membrane. Ergosterol falls, intermediates toxic to the fungus itself accumulate, growth halts and the membrane collapses. Its grip on that enzyme is tighter than that of the older azoles, which is why it reaches Aspergillus where fluconazole cannot. What makes its use delicate is that the liver metabolises it through enzymes whose activity varies genetically between people, so on the same amount its level runs high in some and low in others — and that is why the blood level is measured.'
  },
  effects: {
    ar: 'أشهر أثر هو اضطراب البصر: رؤية غير طبيعية، وتغيّر في إدراك الألوان، وزيادة سطوع الضوء، ويبدأ عادة بعد التسريب أو الجرعة بوقت قصير ويزول من تلقاء نفسه. ولهذا يُنصح بعدم القيادة ليلاً أثناء العلاج. ويأتي بعده الحرارة والغثيان والقيء والإسهال والطفح والصداع. وقد ترتفع إنزيمات الكبد في التحاليل. وعند الأطفال يشيع الرعاف. ومع طول الاستعمال قد يظهر ألم في العظام أو المفاصل. أغلب هذه الأعراض مقبولة أمام خطورة العدوى، لكن كلّها تُبلَّغ للفريق لأنها قد تعني أن مستوى الدواء صار أعلى مما ينبغي.',
    en: 'The best-known effect is visual disturbance: abnormal vision, altered colour perception and increased brightness of light, usually starting shortly after a dose or infusion and passing on its own. For that reason night driving is discouraged during treatment. Next come fever, nausea, vomiting, diarrhoea, rash and headache. Liver enzymes may rise on testing. In children, nosebleeds are common. With long use, bone or joint pain may appear. Most of these are acceptable against the seriousness of the infection, but all are reported to the team, because they may mean the drug level has climbed higher than it should.'
  },
  warning: {
    ar: 'اطلبي المساعدة فوراً عند اصفرار العينين أو الجلد أو بول داكن أو ألم أعلى البطن اليمين — سُجّلت تفاعلات كبدية خطيرة وفشل كبدي خاطف. وأبلغي فوراً إن استمرّ اضطراب البصر أو ساء أو ظهر ألم في العين أو نقص في الرؤية، فقد سُجّل التهاب في العصب البصري ووذمة حليمة. واطلبي الطوارئ عند خفقان شديد أو إغماء، فقد سُجّل تسرّع بطيني نادر. وأي طفح جديد يستدعي مراجعة فورية، وخاصة إن تقرّح أو تقشّر. وأبلغي عن هلوسة أو تشوّش ذهني. وأي بقعة جلدية جديدة قاسية أو قرحة لا تلتئم بعد علاج طويل تُعرض على الطبيب فوراً.',
    en: 'Get help at once for yellowing of the eyes or skin, dark urine or pain in the upper right abdomen — serious hepatic reactions and fulminant liver failure have been recorded. Report immediately if visual disturbance persists or worsens, or if eye pain or loss of vision appears, as optic neuritis and papilloedema have been reported. Seek emergency care for severe palpitations or fainting, as rare ventricular tachycardia has occurred. Any new rash needs prompt review, especially if it blisters or peels. Report hallucinations or confusion. And any new hard patch of skin or a sore that will not heal after long treatment must be shown to a doctor at once.'
  },
  interact: {
    ar: 'ممنوع جمعه مع ما يُسرّع تكسيره فيُفقده مفعوله: الريفامبين، والكاربامازيبين، والباربيتورات طويلة الأثر، والريتونافير بجرعة عالية، ونبتة سانت جون العشبية. وممنوع مع أدوية يرفع مستواها إلى حدّ خطر: السيروليموس، وقلويدات الشقران، والبيموزيد. ويحتاج ضبطاً ومتابعة مع الفينيتوين، والوارفارين حيث يُراقَب مؤشّر التخثّر، ومع مضادات الفطريات الأخرى، والأوميبرازول، ومضادات الالتهاب غير الستيرويدية. وجمعه مع الكورتيزون يرفع خطر خلل الغدّة الكظرية. ولا يُبدأ أي دواء أو مكمّل عشبي أثناءه إلا بعد مراجعة الصيدلي، ويُصحَّح نقص البوتاسيوم والمغنيسيوم قبل البدء.',
    en: 'It must not be combined with anything that speeds its breakdown and strips its effect: rifampicin, carbamazepine, long-acting barbiturates, high-dose ritonavir and St John’s wort. It is also contraindicated with medicines whose levels it raises dangerously: sirolimus, ergot alkaloids and pimozide. It needs adjustment and monitoring with phenytoin, with warfarin where clotting is watched, with other antifungals, with omeprazole and with non-steroidal anti-inflammatories. Combining it with corticosteroids raises the risk of adrenal dysfunction. No medicine or herbal supplement is started during it without pharmacist review, and low potassium and magnesium are corrected before it begins.'
  },
  avoid: {
    ar: 'ممنوع في الحمل: أظهرت الدراسات تشوّهات جنينية وسمّية على الجنين، وتُستعمل وسيلة منع حمل موثوقة أثناء العلاج. ولا يُنصح بالرضاعة أثناءه. وممنوع مع الأدوية المذكورة في التعارضات. ويُتوخّى الحذر عند من عنده مرض كبدي، ومن عنده اضطراب في نظم القلب أو خلل في أملاح الدم. والشكل الوريدي يُتجنّب عند ضعف تصفية الكلية لأن المذيب يتراكم. ويُمنع عن من عنده عدم تحمّل وراثي للغالاكتوز. ⛔ وقاعدة تُقال لكل مريض عليه: ابتعدي عن الشمس المباشرة تماماً واستعملي واقياً قوياً ولباساً ساتراً — فقد ظهر سرطان جلد حرشفي عند بعض من تفاعلوا مع الشمس أثناء العلاج الطويل.',
    en: 'It is contraindicated in pregnancy: studies showed fetal malformations and embryotoxicity, and reliable contraception is used during treatment. Breastfeeding is not advised during it. It is contraindicated with the medicines listed under interactions. Caution applies in liver disease and in anyone with a cardiac rhythm disturbance or a blood salt imbalance. The intravenous form is avoided when renal clearance is reduced, because its solubilising vehicle accumulates. It is withheld from anyone with hereditary galactose intolerance. And one rule is told to every patient on it: stay out of direct sunlight entirely and use strong sun protection and covering clothing — squamous cell skin cancer has developed in some people who reacted to the sun during long-term therapy.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a605022.html',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ce3ef5cf-3087-4d92-9d94-9eb8287228db'
  ]
};

/* ── ٧) التيربينافين ──────────────────────────────────────── */
RX_BODY['terbinafine'] = {
  what: {
    ar: 'مضاد فطريات من فصيلة الأليلامينات، وهي فصيلة تختلف عن الآزولات في موضع عملها. يوجد بشكلين مختلفَين تماماً في وزنهما: كريم أو جل أو بخّاخ يُدهن على الجلد وتُصرف بلا وصفة وأثره موضعي، وأقراص تُبتلع وتدخل الدم وتتركّز في الجلد والشعر والأظافر. الأقراص هي أفعل ما لدينا لفطر الأظافر ولسعفة فروة الرأس، لكنها تُطلب بوصفة ومتابعة، لأن ثقلها على الكبد وعلى حاسّة الذوق ليس تفصيلاً هيّناً.',
    en: 'An allylamine antifungal, a family that differs from the azoles in where it acts. It exists in two forms of very different weight: a cream, gel or spray applied to the skin, sold without prescription, with a local effect; and tablets that are swallowed, enter the blood and concentrate in skin, hair and nails. The tablets are the most effective thing we have for nail fungus and scalp ringworm, but they require a prescription and monitoring, because their burden on the liver and on the sense of taste is not a trivial detail.'
  },
  why: {
    ar: 'الأقراص تُستعمل لفطريات الأظافر في اليد والقدم، ولسعفة فروة الرأس عند الأطفال وهي حالة لا يكفيها أي دهان لأن الفطر يسكن داخل الشعرة. أما الكريم والبخّاخ فيُستعملان لسعفة القدم، والقوباء الحلقية في الجسم، وسعفة الأربية، والنخالية المبرقشة. والفرق بين الشكلين ليس في القوّة فقط بل في الوصول: ما يصيب سطح الجلد يكفيه الدهان، وما يسكن داخل صفيحة الظفر أو داخل الشعرة لا يبلغه إلا ما يجري في الدم. ويُفضَّل تأكيد فطر الظفر بمزرعة قبل بدء أقراص طويلة الأمد.',
    en: 'The tablets are used for fungal infection of fingernails and toenails, and for scalp ringworm in children, a condition no ointment can settle because the fungus lives inside the hair shaft. The cream and spray are used for athlete’s foot, ringworm of the body, jock itch and pityriasis versicolor. The difference between the two forms is not only strength but reach: what sits on the skin surface is met by an applied treatment, while what lives inside the nail plate or the hair shaft is reached only by what travels in the blood. Confirming nail fungus by culture is preferred before starting a long tablet course.'
  },
  how: {
    ar: 'الفطر يبني غشاءه من الإرغوستيرول، لكن التيربينافين يضرب خطوة أبكر من الآزولات: يعطّل إنزيم سكوالين إيبوكسيداز الذي يبدأ سلسلة التصنيع. فينقطع الإمداد بالإرغوستيرول من جهة، ويتراكم السكوالين داخل الخلية من الجهة الأخرى حتى يصير سامّاً لها، فتموت. ولهذا يوصف بأنه قاتل للفطر لا مُبطئ لنموّه فقط، وهذا سبب تفوّقه على الأظافر. ويذوب في الدهون فيتراكم في القرنية الجلدية وفي الظفر ويبقى فيهما بعد آخر قرص، فيستمرّ الأثر بينما يزحف الظفر السليم مكان المصاب — وهذا هو سبب طول الانتظار قبل رؤية النتيجة.',
    en: 'A fungus builds its membrane from ergosterol, but terbinafine strikes a step earlier than the azoles: it disables squalene epoxidase, the enzyme that begins the synthesis chain. The supply of ergosterol is cut on one side, while squalene builds up inside the cell on the other until it becomes toxic to it, and the cell dies. That is why it is described as fungicidal rather than merely growth-slowing, and why it outperforms on nails. It dissolves in fat, so it accumulates in the horny layer of skin and in the nail and stays there after the last tablet, the effect continuing while healthy nail creeps up to replace the diseased one — which is why the result takes so long to see.'
  },
  effects: {
    ar: 'مع الأقراص: طفح، وصداع، وإسهال، وغثيان أو قيء، ونقص شهية، وألم في المعدة أو عسر هضم، وألم في العضلات أو المفاصل، ودوخة. ومنها ما يزعج أكثر مما يخيف: فقدان حاسّة التذوّق، وهو شائع ويعود عادة بعد إيقاف الدواء، لكنه قد يُنقص الشهية والوزن ويُدخل صاحبه في ضيق نفسي. ومع الكريم والبخّاخ: تقشّر أو حكّة أو حرقة موضعية في مكان الدهان، وتخفّ بتقليل الكمية. والدوخة والصداع يخفّان بالراحة وشرب الماء وتقليل الكحول، وعسر الهضم يخفّ بتقليل القهوة.',
    en: 'With the tablets: rash, headache, diarrhoea, nausea or vomiting, reduced appetite, stomach ache or indigestion, muscle or joint pain and dizziness. Some of these trouble more than they frighten: loss of the sense of taste is common and usually returns after stopping, but it can reduce appetite and weight and leave the person low. With the cream and spray: peeling, itching or local burning where it is applied, easing if less is used. Dizziness and headache ease with rest, fluids and less alcohol, and indigestion eases with less coffee.'
  },
  warning: {
    ar: 'أوقفي الأقراص واطلبي مساعدة عاجلة إن اصفرّ بياض العينين أو الجلد، أو صار البول داكناً والبراز شاحباً، أو جاءك غثيان مستمرّ مع فقدان شهية وتعب شديد وألم أعلى البطن اليمين — هذه علامات أذى الكبد، وهو أخطر ما في هذا الدواء وقد لا يُشعر به إلا في التحاليل. واطلبي مساعدة عاجلة إن صرت تُكدَمين بسهولة أو تلتقطين العدوى بسرعة، أو جاءتك حرارة مع طفح وتعب غير معتاد، أو ألم شديد أعلى البطن ينفذ إلى الظهر، أو ضعف عضلي مع بول داكن. واطلبي الإسعاف عند انتفاخ الشفتين أو اللسان أو الحلق، أو طفح ينتفخ ويتقرّح ويتقشّر.',
    en: 'Stop the tablets and seek urgent help if the whites of the eyes or the skin turn yellow, urine darkens and stools go pale, or persistent nausea comes with loss of appetite, severe tiredness and pain in the upper right abdomen — these are signs of liver injury, the most dangerous thing about this drug, and it may be felt only in the blood tests. Seek urgent help if you begin bruising easily or catching infections quickly, if fever comes with a rash and unusual tiredness, if severe upper abdominal pain bores through to the back, or if muscle weakness comes with dark urine. Call the emergency services for swelling of the lips, tongue or throat, or a rash that swells, blisters and peels.'
  },
  interact: {
    ar: 'التيربينافين يعطّل إنزيماً كبدياً اسمه سي واي بي اثنان دي ستّة، وهو الذي يستقلب أدوية كثيرة، فترتفع مستوياتها معه: بعض حاصرات بيتا كالميتوبرولول، وكثير من مضادات الاكتئاب ثلاثية الحلقة ومثبّطات استرداد السيروتونين، وبعض مضادات الذهان، وأدوية اضطراب النظم. والسيميتيدين يرفع مستوى التيربينافين، والريفامبين يخفضه فيُضعف مفعوله. والكافيين يبقى في الجسم أطول معه فقد تزيد العصبية والأرق. ولا يُبدأ دواء جديد أثناء العلاج بالأقراص إلا بعد مراجعة الصيدلي. أما الكريم والبخّاخ فتعارضاتهما مهملة لأن ما يدخل الدم منهما قليل جداً.',
    en: 'Terbinafine disables a liver enzyme called CYP2D6, which metabolises many medicines, so their levels rise alongside it: some beta blockers such as metoprolol, many tricyclic antidepressants and serotonin reuptake inhibitors, some antipsychotics, and antiarrhythmic drugs. Cimetidine raises the level of terbinafine, while rifampicin lowers it and weakens its effect. Caffeine stays in the body longer with it, so jitteriness and sleeplessness may increase. No new medicine should be started during a tablet course without pharmacist review. For the cream and spray interactions are negligible, because very little of them enters the blood.'
  },
  avoid: {
    ar: 'الأقراص ممنوعة على من عنده مرض كبدي مزمن أو نشط، ولمن سبق أن تحسّس من التيربينافين. ويُنصح بفحص إنزيمات الكبد قبل البدء وبإعادته أثناء العلاج. وتُتجنّب الأقراص في الحمل والرضاعة. وتحتاج حذراً عند من عنده مرض كلوي، ومن عنده ذئبة حمامية لأن الدواء قد يُثيرها أو يُظهر صورة جلدية منها، ومن ضعفت مناعته. أما الكريم والبخّاخ فأبسط بكثير، ومع ذلك لا يُوضعان في العين ولا داخل الفم ولا على جلد متقرّح، ويُراجَع الطبيب إن لم تتحسّن المنطقة أو زاد الاحمرار والألم بدل أن يقلّ.',
    en: 'The tablets are contraindicated in anyone with chronic or active liver disease and in anyone with a previous reaction to terbinafine. Liver enzymes are checked before starting and rechecked during treatment. The tablets are avoided in pregnancy and breastfeeding. Caution applies in kidney disease, in lupus erythematosus because the drug may provoke it or bring out a skin form of it, and in weakened immunity. The cream and spray are far simpler, yet still are not put in the eye, inside the mouth or on broken skin, and a doctor is consulted if the area does not improve or if redness and pain increase instead of settling.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a699061.html',
    'https://www.nhs.uk/medicines/terbinafine/side-effects-of-terbinafine/',
    'https://www.ncbi.nlm.nih.gov/books/NBK545218/'
  ]
};

/* ── ٨) الجريزوفولفين ─────────────────────────────────────── */
RX_BODY['griseofulvin'] = {
  what: {
    ar: 'أقدم مضاد فطريات يُبتلع، مستخرج من فطر من جنس البنسيليوم، وظلّ عقوداً الخيار الوحيد لسعفة فروة الرأس عند الأطفال قبل ظهور البدائل. يوجد أقراصاً وشراباً بحجمَي جسيمات: دقيق وفائق الدقّة، والثاني يُمتصّ أفضل. وامتصاصه يتوقّف على الدهن في الطعام، فيُؤخذ مع وجبة دسمة وإلا ضاع أغلبه. مداه ضيّق بحكم تصميمه: يعمل على الفطر الجلدي وحده — سعفة الجلد والشعر والأظافر — ولا يمسّ الخمائر ولا البكتيريا ولا بقيّة الفطريات.',
    en: 'The oldest swallowed antifungal, extracted from a Penicillium mould, and for decades the only option for scalp ringworm in children before alternatives appeared. It comes as tablets and a suspension in two particle sizes, microsize and ultramicrosize, the latter better absorbed. Its absorption depends on fat in the food, so it is taken with a rich meal or most of it is lost. Its range is narrow by design: it acts on dermatophytes alone — ringworm of skin, hair and nails — and does not touch yeasts, bacteria or other fungi.'
  },
  why: {
    ar: 'يُستعمل لعدوى الفطر الجلدي المؤكّدة: سعفة الجسم، وسعفة القدم، وسعفة الأربية، وسعفة اللحية، وسعفة فروة الرأس، وسعفة الأظافر. والنشرة تشترط شرطاً واضحاً: يُثبَت قبل العلاج أن الفطر الجلدي هو المسؤول عن العدوى، لأن هذا الدواء لا يفيد في غيره. ومكانه الطبيعي اليوم هو ما لا يكفيه الدهان: فروة الرأس التي يسكنها الفطر داخل الشعرة، أو انتشار واسع في الجلد لم يستجب للموضعي. وهو صريح فيما لا يعالجه: لا يعالج فطريات المبيضات ولا العدوى البكتيرية ولا الفطريات الأخرى.',
    en: 'It is used for confirmed dermatophyte infection: ringworm of the body, of the foot, of the groin, of the beard area, of the scalp and of the nails. The label sets a clear condition: before therapy a dermatophyte should be identified as responsible for the infection, because this drug is of no use in anything else. Its natural place today is what an applied treatment cannot settle: a scalp where the fungus lives inside the hair shaft, or wide spread on the skin that has not responded to topical treatment. And it is explicit about what it does not treat: not candidiasis, not bacterial infection, and not other fungal conditions.'
  },
  how: {
    ar: 'لا يهاجم الجريزوفولفين غشاء الفطر كما تفعل الآزولات، بل ينقضّ على انقسامه: يرتبط ببروتينات الأنيبيبات الدقيقة التي تصنع مغزل الانقسام، فتعجز الخلية عن قسمة نفسها ويتوقّف تكاثر الفطر. والمهمّ في مساره أنه يُودَع في الكيراتين — مادّة الجلد والشعر والظفر — فيجعل الكيراتين الجديد النامي مقاوماً لغزو الفطر. أي أن الشفاء لا يقع بقتل ما هو موجود بل بأن ينمو نسيج جديد محصّن يزحف مكان المصاب. ولهذا يطول العلاج، ولهذا يعود المرض إن أُوقف الدواء قبل أن يُستبدل النسيج كلّه.',
    en: 'Griseofulvin does not attack the fungal membrane the way azoles do; it attacks its division: it binds the microtubule proteins that build the mitotic spindle, so the cell cannot divide and the fungus stops multiplying. What matters about its route is that it is deposited in keratin — the material of skin, hair and nail — making newly growing keratin resistant to fungal invasion. That is, the cure comes not by killing what is there but by growing new, protected tissue that creeps up to replace the diseased part. Hence the length of treatment, and hence the relapse if the drug is stopped before all the tissue has been replaced.'
  },
  effects: {
    ar: 'أكثر ما يُشتكى منه: صداع، واضطراب في المعدة، وقيء، وإسهال أو براز رخو، وعطش، وتعب، ودوخة أو شعور بقرب الإغماء. وأغلب تفاعلاته حين تقع تكون من نوع التحسّس: طفح جلدي وشرى. وقد يظهر خدر أو وخز في اليدين والقدمين مع العلاج الممتدّ، وهو نادر. والصداع كثيراً ما يخفّ مع استمرار العلاج. أما الأثر الذي يجب أن يعرفه كل من يأخذه فهو أن الجلد يصير شديد الحساسية للشمس، فالتعرّض الطويل للشمس الطبيعية أو الصناعية يحتاج حذراً وواقياً ولباساً ساتراً.',
    en: 'The commonest complaints are headache, upset stomach, vomiting, diarrhoea or loose stools, thirst, tiredness, and dizziness or faintness. Most reactions, when they occur, are of the hypersensitivity type: skin rash and hives. Numbness or tingling in the hands and feet may appear with extended therapy, though rarely. Headache often eases as treatment continues. But the effect everyone taking it should know is that the skin becomes highly sensitive to sunlight, so prolonged exposure to natural or artificial sun calls for caution, sun protection and covering clothing.'
  },
  warning: {
    ar: 'اطلبي مساعدة فورية عند حرارة، أو التهاب حلق، أو تقرّح وتهيّج في الفم — فهذه قد تدلّ على نقص في كريات الدم البيضاء. واطلبي مساعدة فورية عند اصفرار العينين أو الجلد أو بول داكن، فقد سُجّلت حالات كبدية شديدة أدّت إلى دخول المستشفى أو الوفاة. وأي طفح جديد يستدعي إيقافاً ومراجعة فورية، وخاصة إن انتفخ أو تقرّح أو تقشّر الجلد، فقد سُجّلت متلازمة ستيفنز جونسون وانحلال البشرة السمّي وحمامى عديدة الأشكال. واطلبي الإسعاف عند انتفاخ الوجه أو الشفتين أو الحلق أو ضيق النفس. وإن حدث حمل أثناء العلاج فاتصلي بالطبيب فوراً.',
    en: 'Seek immediate help for fever, a sore throat, or soreness and irritation of the mouth — these may point to a fall in white blood cells. Seek immediate help for yellowing of the eyes or skin or dark urine, as severe hepatic events leading to hospitalisation or death have been reported. Any new rash calls for stopping and prompt review, especially if the skin swells, blisters or peels, since Stevens-Johnson syndrome, toxic epidermal necrolysis and erythema multiforme have been reported. Call the emergency services for swelling of the face, lips or throat, or breathlessness. And if pregnancy occurs during treatment, contact the doctor at once.'
  },
  interact: {
    ar: '⛔ أهمّ تعارضَين يجب ألا يُنسيا: الأول أنه يُضعف حبوب منع الحمل والوسائل الهرمونية عموماً فيقع الحمل رغم أخذها، فتلزم وسيلة إضافية غير هرمونية أثناء العلاج. والثاني أنه يُنقص فاعلية الوارفارين المميّع فيحتاج مؤشّر التخثّر مراقبة وتعديلاً. والكحول: يزيد الجريزوفولفين أثرها فقد يظهر تسارع في النبض واحمرار في الوجه، ومن كان له تاريخ مع الكحول يُخبر طبيبه. والباربيتورات تُنقص فاعليته فيضعف العلاج. والساليسيلات قد تتفاعل معه. وأخبري الطبيب بكل دواء تأخذينه قبل البدء.',
    en: 'Two interactions must never be forgotten. The first is that it weakens the contraceptive pill and hormonal methods generally, so pregnancy can occur despite them, and an additional non-hormonal method is needed during treatment. The second is that it reduces the effectiveness of the blood thinner warfarin, so clotting measurements need watching and adjusting. Alcohol: griseofulvin potentiates its effect, so a fast heartbeat and facial flushing may appear, and anyone with a history around alcohol should tell their doctor. Barbiturates reduce its activity and weaken treatment. Salicylates may interact. Tell the doctor every medicine you take before starting.'
  },
  avoid: {
    ar: 'ممنوع في الحمل ولمن تخطّط للحمل، فقد يُحدث أذى للجنين. وممنوع عند البورفيريا وعند فشل الخلايا الكبدية، ولمن سبق أن تحسّس منه. ولا يُنصح به أثناء الرضاعة. ويُخبَر الطبيب عن أي مرض كبدي وعن الذئبة الحمامية. وللرجال: يُنصح بتأجيل الإنجاب فترة بعد انتهاء العلاج يحدّدها الطبيب. وللنساء: تُستعمل وسيلة منع حمل موثوقة غير هرمونية أثناء العلاج وبعده لفترة يحدّدها الطبيب. وأخيراً: تجنّبي الشمس المباشرة الطويلة واستعملي واقياً ولباساً ساتراً، وراجعي إن لم تتحسّن الحالة كما يُتوقّع.',
    en: 'It is contraindicated in pregnancy and in women planning pregnancy, as it may cause fetal harm. It is contraindicated in porphyria and in hepatocellular failure, and in anyone with previous hypersensitivity to it. It is not advised while breastfeeding. Tell the doctor about any liver disease and about lupus erythematosus. For men: fathering a child is advised to be postponed for a period after treatment ends, set by the doctor. For women: a reliable non-hormonal contraceptive method is used during treatment and for a period afterwards set by the doctor. Finally: avoid long direct sun exposure, use sun protection and covering clothing, and seek review if the condition does not improve as expected.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682295.html',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=98829d90-b289-4bec-a625-7af412a5cb2d',
    'https://www.ncbi.nlm.nih.gov/books/NBK537323/'
  ]
};

/* ── ٩) النيستاتين ────────────────────────────────────────── */
RX_BODY['nystatin'] = {
  what: {
    ar: 'مضاد فطريات من فصيلة البوليينات، أي المركّبات نفسها التي ينتمي إليها أمفوتريسين ب، لكن النيستاتين يختلف عنه اختلافاً جوهرياً في مساره: لا يُمتصّ من الأمعاء إلا بمقدار مهمل، فلا تظهر له مستويات تُذكر في الدم، ويخرج أغلبه في البراز كما دخل. يوجد شراباً يُمضمض ويُبلَع، وأقراصاً، ومرهماً وكريماً وبودرة للجلد، وتحاميل مهبلية. وهذا القصور في الامتصاص هو سرّ أمانه وسرّ حدّه معاً: يعمل حيث يلامس فقط، ولا شأن له بما هو داخل الجسم.',
    en: 'A polyene antifungal — the same family as amphotericin B — but nystatin differs from it fundamentally in its route: it is absorbed from the gut only negligibly, so no meaningful blood level appears, and most of it leaves in the stool as it came. It exists as a suspension that is swished and swallowed, as tablets, as an ointment, cream and powder for the skin, and as vaginal pessaries. This failure to be absorbed is at once the secret of its safety and the secret of its limit: it works only where it touches, and has nothing to do with what is inside the body.'
  },
  why: {
    ar: 'يُستعمل لعدوى المبيضات حيث يمكن ملامستها: القلاع في تجويف الفم واللسان والحلق، وفطريات الجلد في الثنايا والطيّات، وطفح الحفاض حين تدخله الخميرة، وفطريات المهبل. وهو خيار مألوف عند الرضّع لأن ما يُمتصّ منه لا يكاد يُذكر. ويُستعمل كذلك عند من ضعفت مناعتهم لمعالجة القلاع المتكرّر أو الوقاية منه. والنشرة تقول صراحةً ما لا يفعله: هو غير فعّال في العدوى الفطرية الجهازية، لأنه لا يُمتصّ من الأمعاء أصلاً، فلا يبلغ الدم ولا الأعضاء.',
    en: 'It is used for candida infection wherever it can be touched: thrush of the mouth cavity, tongue and throat; skin yeast in folds and creases; nappy rash when yeast enters it; and vaginal thrush. It is a familiar choice in infants because what is absorbed from it is barely worth mentioning. It is also used in people with weakened immunity to treat or prevent recurrent thrush. And the label says plainly what it does not do: it is not effective in systemic fungal infection, because it is not significantly absorbed from the gastrointestinal tract, so it never reaches the blood or the organs.'
  },
  how: {
    ar: 'يرتبط النيستاتين بالستيرولات في غشاء الخلية الفطرية، وأهمّها الإرغوستيرول، وارتباطه به أقوى بكثير من ارتباطه بالكوليسترول في أغشيتنا، وهذا الفرق هو ما يجعله يختار الفطر ويترك خلايانا. وحين يرتبط تتجمّع جزيئاته فتفتح في الغشاء ثقوباً حقيقية، فيتسرّب البوتاسيوم وسائر ما بداخل الخلية إلى الخارج، فتفقد الخلية توازنها وتموت. أي أنه لا يبطئ نموّ الفطر بل يخرق جداره. وهو أثر يقع في اللحظة التي يلامس فيها الغشاء — ولهذا يُطلب من المريض أن يُبقي الشراب في فمه أطول ما يستطيع قبل بلعه.',
    en: 'Nystatin binds the sterols in the fungal cell membrane, chiefly ergosterol, and its grip there is far stronger than its grip on the cholesterol in our own membranes — and that difference is what makes it pick out the fungus and leave our cells alone. Once bound, its molecules gather and open real pores in the membrane, so potassium and the rest of the cell contents leak out, the cell loses its balance and dies. It does not slow the fungus down; it breaches its wall. And the effect happens the moment it touches the membrane — which is why the patient is asked to hold the suspension in the mouth as long as possible before swallowing.'
  },
  effects: {
    ar: 'مع الشراب والأقراص: إسهال، وغثيان أو قيء، وانتفاخ أو انزعاج في المعدة، وأحياناً حرقة أو تهيّج في الفم. وهذه أعراض خفيفة عموماً وتخفّ بأخذ الدواء بعد الوجبات وبتناول طعام بسيط وشرب الماء على رشفات. ومع الكريم والمرهم: قد يظهر جفاف أو حكّة أو تورّم بسيط في الجلد مكان الوضع. ويُفضَّل عدم أخذ دواء آخر مضاد للإسهال من الصيدلية دون سؤال الصيدلي. والقاعدة العامة أن الدواء يُكمَل إلى نهاية ما وصفه الطبيب حتى لو ذهبت الأعراض، لأن الخميرة تعود سريعاً إن تُرك مبكّراً.',
    en: 'With the suspension and tablets: diarrhoea, nausea or vomiting, bloating or stomach discomfort, and sometimes burning or irritation in the mouth. These are generally mild and ease by taking it after meals, eating plainly and sipping water. With the cream and ointment: dryness, itching or mild swelling of the skin where it is applied may appear. It is better not to take another anti-diarrhoeal from the pharmacy without asking the pharmacist. And the general rule is to finish the course the doctor prescribed even after symptoms clear, because the yeast returns quickly if it is left early.'
  },
  warning: {
    ar: 'أوقفي الدواء واتصلي بالطبيب أو الصيدلي عند شرى أو طفح أو حكّة، أو حرقة وتهيّج في الفم لم تكن موجودة، أو ظهور طفح أو جفاف أو تورّم في الجلد مكان الكريم. واطلبي الإسعاف فوراً عند انتفاخ مفاجئ في الشفتين أو الفم أو الحلق أو اللسان، أو صعوبة في التنفّس أو البلع، أو ضيق في الحلق، أو ازرقاق الشفتين، أو تشوّش وإغماء، أو طفح منتفخ متقرّح متقشّر — فقد سُجّلت تفاعلات تحسّسية شبيهة بالتأق. وراجعي الطبيب إن لم تتحسّن العدوى أو عادت بعد انتهاء العلاج، فقد يكون التشخيص غير الذي ظُنّ.',
    en: 'Stop the medicine and contact a doctor or pharmacist for hives, a rash or itching; for burning and irritation of the mouth that was not there before; or if a rash, dryness or swelling appears on the skin where the cream is applied. Call the emergency services immediately for sudden swelling of the lips, mouth, throat or tongue, difficulty breathing or swallowing, tightness in the throat, blue lips, confusion and fainting, or a rash that is swollen, blistered or peeling — anaphylactoid reactions have been reported. And see a doctor if the infection does not improve or returns after the course ends, since the diagnosis may not be what was assumed.'
  },
  interact: {
    ar: 'لأن النيستاتين لا يُمتصّ من الأمعاء ولا يبلغ الدم بمقادير تُذكر، فإن قائمة تعارضاته مع الأدوية الأخرى قصيرة جداً مقارنة بمضادات الفطريات التي تُبتلَع وتُمتصّ. ومع ذلك تبقى قاعدة السلامة قائمة: أخبري الطبيب أو الصيدلي بكل ما تأخذينه من أدوية بوصفة أو بغير وصفة، ومن مكمّلات وأعشاب، قبل البدء. ولا تُخلط تحاميل المهبل مع مستحضرات مهبلية أخرى في الوقت نفسه بلا استشارة. ولا تُوضع الأشكال الجلدية على جروح مفتوحة أو جلد متقرّح إلا بإذن. ولا يُستبدل به علاج جهازي وُصف لعدوى داخلية.',
    en: 'Because nystatin is not absorbed from the gut and does not reach the blood in meaningful amounts, its list of interactions with other medicines is very short compared with antifungals that are swallowed and absorbed. Even so the safety rule stands: tell the doctor or pharmacist everything you take — prescription and non-prescription medicines, supplements and herbal products — before starting. Vaginal pessaries should not be mixed with other vaginal preparations at the same time without advice. The skin forms are not applied to open wounds or broken skin without permission. And it is never substituted for a systemic treatment prescribed for an infection inside the body.'
  },
  avoid: {
    ar: 'ممنوع على من ثبتت عنده حساسية من النيستاتين أو من أي مكوّن في المستحضر، ويُوقف فوراً إن ظهر تحسّس أو تهيّج. وهو من أهدأ مضادات الفطريات عند الرضّع والأطفال بحكم قلّة امتصاصه، لكن استعماله عندهم يبقى بمشورة الطبيب أو الصيدلي. وفي الحمل والرضاعة: أخبري طبيبك إن كنت حاملاً أو تخطّطين للحمل أو ترضعين، واتصلي به إن حدث حمل أثناء الاستعمال. وأخيراً حدّ يجب أن يكون واضحاً: هذا الدواء لا يصلح لعدوى فطرية داخل الجسم أبداً — فمن عنده حمّى أو تعب شديد أو عدوى منتشرة يحتاج تقييماً وعلاجاً آخر.',
    en: 'It is contraindicated in anyone with proven hypersensitivity to nystatin or to any component of the preparation, and is stopped at once if sensitisation or irritation appears. It is among the gentlest antifungals in infants and children given how little is absorbed, but its use in them still goes through a doctor or pharmacist. In pregnancy and breastfeeding: tell your doctor if you are pregnant, planning pregnancy or breastfeeding, and contact them if pregnancy occurs during use. And finally a limit that must be clear: this medicine is never suitable for a fungal infection inside the body — anyone with fever, severe fatigue or spreading infection needs a different assessment and a different treatment.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682758.html',
    'https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=8ce02e76-303c-4e06-a47e-0a7bbf46c3f2',
    'https://www.nhs.uk/medicines/nystatin/side-effects-of-nystatin/'
  ]
};

/* ── ١٠) الكلوتريمازول ────────────────────────────────────── */
RX_BODY['clotrimazole'] = {
  what: {
    ar: 'مضاد فطريات موضعي من فصيلة الإيميدازولات، وهو من أوسع مضادات الفطريات انتشاراً في البيوت لأنه يُصرف بلا وصفة في أغلب صوره. يوجد كريماً ومحلولاً وبخّاخاً للجلد، وتحاميل وكريماً مهبلياً، وقطرات للأذن، وأقراص مصّ تذوب في الفم لعلاج القلاع. مبدؤه أنه يعمل حيث يُوضع: ما يدخل الدم منه عبر الجلد قليل جداً، ولهذا كان أثره العام محدوداً وتعارضاته قليلة. وهو خيار أول لكثير من الفطريات السطحية التي تصيب سطح الجلد والأغشية.',
    en: 'A topical imidazole antifungal, among the most widely kept antifungals in homes because most of its forms are sold without prescription. It comes as a cream, solution and spray for the skin, as pessaries and vaginal cream, as ear drops, and as lozenges that dissolve in the mouth for thrush. Its principle is that it acts where it is put: very little enters the blood through the skin, so its systemic effect is limited and its interactions few. It is a first choice for many of the superficial fungal infections that strike the skin surface and the mucous membranes.'
  },
  why: {
    ar: 'يُستعمل لفطريات المهبل، ولفطريات الحشفة عند الرجال، ولفطريات الجلد عموماً: سعفة القدم، والقوباء الحلقية، وسعفة الأربية، والنخالية المبرقشة، والطفح في ثنايا الجلد حيث الرطوبة، وطفح الحفاض حين تدخله الخميرة. وله شكل قطرات لالتهاب الأذن حين يكون سببه فطرياً. وله قرص مصّ لعلاج القلاع في الفم. وهو لا يصلح لفطريات الأظافر لأن ما يُوضع على السطح لا يخترق صفيحة الظفر — وهذه نقطة يخطئ فيها كثيرون فيدهنون الظفر شهوراً بلا نتيجة.',
    en: 'It is used for vaginal thrush, for thrush on the penis, and for skin fungus generally: athlete’s foot, ringworm, jock itch, pityriasis versicolor, rashes in skin folds where moisture gathers, and nappy rash when yeast enters it. It has a drop form for ear inflammation when the cause is fungal, and a lozenge for thrush in the mouth. It is not suitable for nail fungus, because what is applied to the surface does not penetrate the nail plate — a point many people get wrong, painting a nail for months with no result.'
  },
  how: {
    ar: 'يعطّل الكلوتريمازول خطوة في تصنيع الإرغوستيرول، وهو المادّة الدهنية التي يقوم عليها غشاء الخلية الفطرية: يمنع نزع مجموعة الميثيل عن اللانوستيرول، فيتوقّف تحوّله إلى إرغوستيرول. فيصير الغشاء غير قادر على أداء وظيفته، وتتسرّب محتويات الخلية، ويتوقّف نموّ الفطر. وأثره متناسب مع تركيزه في المكان: كلّما بقي ملامساً للمنطقة أطول كان أنفع، ولهذا يُدهن على جلد نظيف جافّ ويُترك. وله عند التراكيز العالية أثر على بعض البكتيريا موجبة الغرام وعلى المشعّرات، لكن هذا ليس ما يُوصف لأجله عادة.',
    en: 'Clotrimazole disables a step in the making of ergosterol, the fatty substance the fungal cell membrane rests on: it prevents the removal of a methyl group from lanosterol, so its conversion into ergosterol stops. The membrane becomes unable to do its job, the cell contents leak out, and fungal growth halts. Its effect is proportional to its concentration in place: the longer it stays in contact with the area the better it works, which is why it is applied to clean dry skin and left there. At high concentrations it also acts on some gram-positive bacteria and on Trichomonas, but that is not usually what it is prescribed for.'
  },
  effects: {
    ar: 'مع الكريم والمحلول والبخّاخ: تهيّج في الجلد، واحمرار، وحكّة، وألم أو حرقة أو لسعة مكان الوضع، وأغلبها خفيف ويهدأ بعد أيام. ومع الأشكال المهبلية: حرقة أو حكّة أو تهيّج داخل المهبل، وأحياناً ألم أو تورّم، أو ألم في أسفل البطن أو الحوض، أو إفرازات أو نزف خفيف. وهذه في مجملها موضعية لأن ما يدخل الدم قليل. ومع أقراص المصّ الفموية قد ترتفع إنزيمات الكبد في التحاليل عند نسبة ليست بالقليلة، فيُتابَع الكبد عند من يستعملها. وإن اشتدّ التهيّج بدل أن يخفّ فهذا يستدعي التوقّف والسؤال.',
    en: 'With the cream, solution and spray: skin irritation, redness, itching, and pain, burning or stinging where it is applied — mostly mild and settling within days. With the vaginal forms: burning, itching or irritation inside the vagina, sometimes pain or swelling, or pain in the lower abdomen or pelvis, or discharge or light bleeding. These are largely local because so little enters the blood. With the oral lozenges liver enzymes may rise on testing in a not-insignificant proportion of users, so the liver is monitored in people using them. And if irritation intensifies instead of easing, that calls for stopping and asking.'
  },
  warning: {
    ar: 'أوقفي الدواء وراجعي الطبيب عند طفح أو شرى، أو ألم في المعدة، أو حرارة أو قشعريرة، أو غثيان وقيء، أو إفرازات مهبلية غير معتادة — فهذه علامات تتجاوز التهيّج الموضعي. واطلبي الإسعاف عند انتفاخ الشفتين أو اللسان أو الحلق، أو ضيق نفس وأزيز، أو ازرقاق الشفتين، أو إغماء — فالتأق نادر لكنه ممكن. وقاعدتان عمليتان: إن كانت الحكّة المهبلية أول مرّة في حياتك فلا تعالجيها قبل تشخيص. وإن لم تتحسّن خلال أيام قليلة أو ساءت فراجعي الطبيب بدل تكرار العلبة، فقد يكون السبب غير الفطر أصلاً.',
    en: 'Stop the medicine and see a doctor for a rash or hives, stomach pain, fever or chills, nausea and vomiting, or unusual vaginal discharge — these are signs beyond local irritation. Call the emergency services for swelling of the lips, tongue or throat, breathlessness or wheeze, blue lips, or fainting — anaphylaxis is rare but possible. Two practical rules: if vaginal itching is happening for the first time in your life, do not treat it before a diagnosis. And if it has not improved within a few days, or has worsened, see a doctor rather than repeating the packet, because the cause may not be fungal at all.'
  },
  interact: {
    ar: '⛔ تنبيه عملي يُنسى كثيراً: الكلوتريمازول يُتلف مطّاط اللاتكس، فالواقي الذكري والحاجز المهبلي قد يضعفان ويفشلان في منع الحمل وفي الوقاية من العدوى المنقولة جنسياً، ويمتدّ هذا الضعف أياماً بعد انتهاء العلاج — فتُستعمل وسيلة أخرى في تلك الفترة. ويُتجنّب الجماع والمستحضرات المهبلية الأخرى أثناء العلاج المهبلي. ومن التعارضات الدوائية: التاكروليمس المثبّط للمناعة قد يرتفع مستواه مع الكريم الداخلي والتحاميل. والمستحضرات المهبلية المضادة للفطريات قد تُنقص فاعلية البروجستيرون فلا يُنصح بجمعهما. وتُسأل الصيدلية قبل جمع قطرة أذن مع أخرى.',
    en: 'A practical warning often forgotten: clotrimazole damages latex, so condoms and diaphragms may be weakened and fail both at preventing pregnancy and at protecting against sexually transmitted infection, and that weakening extends for days after treatment ends — so another method is used in that period. Intercourse and other vaginal products are avoided during vaginal treatment. Among drug interactions: the immunosuppressant tacrolimus may rise in level with the internal cream and pessaries. Vaginal antifungal preparations may reduce the effectiveness of progesterone, so combining them is not advised. And ask the pharmacy before combining one ear drop with another.'
  },
  avoid: {
    ar: 'ممنوع على من عنده حساسية معروفة من الكلوتريمازول أو من فصيلة الآزولات. ولا يُوضع في العين، وإن دخل فتُغسل العين فوراً بماء وافر ويُراجَع طبيب العيون إن استمرّ الانزعاج. ولا يُستعمل لفطر الأظافر فهو لا ينفذ إليه. والأشكال المهبلية للبالغات ومن هنّ في سنّ المراهقة فما فوق، ولا تُستعمل عند ظهور حكّة لأول مرّة قبل تشخيص. وفي الحمل والرضاعة: الأشكال الموضعية هي الموصى بها، ولا يُدهن الثدي مباشرة أثناء الرضاعة، وتُسأل الطبيبة قبل الاستعمال. واتصلي بالطبيب إن حدث حمل أثناء الاستعمال. ولا يُوضع على جلد متقرّح أو جرح مفتوح إلا بإذن.',
    en: 'It is contraindicated in anyone with known hypersensitivity to clotrimazole or to the azole family. It is not put in the eye; if it gets in, flush the eye at once with plenty of water and see an eye doctor if discomfort persists. It is not used for nail fungus, which it cannot penetrate. The vaginal forms are for adults and adolescents, and are not used for first-ever itching before a diagnosis. In pregnancy and breastfeeding: the topical forms are the recommended ones, the breast is not treated directly while breastfeeding, and a doctor is asked before use. Contact your doctor if pregnancy occurs during use. And it is not applied to broken skin or an open wound without permission.'
  },
  updated: '2026-09-10',
  src: [
    'https://medlineplus.gov/druginfo/meds/a682753.html',
    'https://www.nhs.uk/medicines/clotrimazole/',
    'https://www.ncbi.nlm.nih.gov/books/NBK560643/'
  ]
};
